def are_equivalent(a, b):
    def proper_divisor_sum(n):
        if n <= 1:
            return 0
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total
    return proper_divisor_sum(a) == proper_divisor_sum(b)
